          ))}
        </nav>
        <Link to={ROUTES.RESERVATION}>
          <Button className="bg-[#D69E2E] hover:bg-[#c28b29] text-white font-semibold rounded-full px-8 py-3 transition-all duration-200">
            Book a Table
          </Button>
        </Link>
      </div>
    </header>
  );
};

export default Header;

