      {/* Sidebar */}
      <aside className="w-64 bg-[#1A202C] text-white flex flex-col">
        <div className="p-6 text-2xl font-bold border-b border-gray-700">
          Admin Panel
        </div>
        <nav className="flex-1 p-4 space-y-2">
          {adminNavItems.map((item) => (
            <Link
              key={item.name}
              to={item.path}
