  const queryClient = useQueryClient();
  return useMutation({
    mutationFn: (reservation: CreateReservationRequest) => createReservation(reservation),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['reservations'] });
    },
  });
};

